CREATE DEFINER=`root`@`localhost` FUNCTION `fn_fecha_nacimiento_aleatoria`(p_edad_min INT, p_edad_max INT) RETURNS date
    NO SQL
    DETERMINISTIC
BEGIN
    DECLARE v_edad_elegida INT;
    DECLARE v_dias_aleatorios INT;
    
    SET v_edad_elegida = FLOOR(p_edad_min + (RAND() * (p_edad_max - p_edad_min + 1)));
    SET v_dias_aleatorios = FLOOR(RAND() * 365);
    RETURN DATE_SUB(CURRENT_DATE(), INTERVAL (v_edad_elegida * 365 + v_dias_aleatorios) DAY);
END ;;
DELIMITER ;
