CREATE DEFINER=`root`@`localhost` FUNCTION `fn_nombre_aleatorio`(p_genero VARCHAR(10)) RETURNS varchar(100) CHARSET utf8mb4
    NO SQL
    DETERMINISTIC
BEGIN
    DECLARE v_gen VARCHAR(1);
    
    IF p_genero = 'H' THEN 
        SET v_gen = 'H';
    ELSEIF p_genero = 'M' THEN 
        SET v_gen = 'M';
    ELSE 
        SET v_gen = IF(RAND() < 0.5, 'H', 'M');
    END IF;
    
    IF v_gen = 'H' THEN
        RETURN ELT(1 + FLOOR(RAND() * 15), 
            'Carlos', 'Luis', 'Pablo', 'Adrian', 'Marco', 'Saul', 'Uriel', 'Jorge', 
            'Fernando', 'Mateo', 'Daniel', 'Alejandro', 'Gabriel', 'Ricardo', 'Javier');
    ELSE
        RETURN ELT(1 + FLOOR(RAND() * 15), 
            'Sofia', 'Maria', 'Ana', 'Valeria', 'Camila', 'Lucia', 'Fernanda', 'Elena', 
            'Gabriela', 'Daniela', 'Mariana', 'Paula', 'Andrea', 'Natalia', 'Isabella');
    END IF;
END ;;
DELIMITER ;
