DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_simular_usuarios`(
    IN p_cantidad INT,              -- Cantidad de registros a generar
    IN p_genero VARCHAR(10),        -- 'H', 'M', o '*' (comodín)
    IN p_pais CHAR(2),              -- Ej: 'US', 'MX', o '*' (comodín)
    IN p_edad_min INT,              -- Edad mínima
    IN p_edad_max INT,              -- Edad máxima
    IN p_prob_activo DECIMAL(5,2)   -- Probabilidad de cuenta activa (Ej: 0.80 para 80%)
)
BEGIN
    DECLARE v_i INT DEFAULT 1;
    DECLARE v_nombre VARCHAR(150);
    DECLARE v_apellido VARCHAR(150);
    DECLARE v_email VARCHAR(120);
    DECLARE v_nickname VARCHAR(100);
    DECLARE v_password VARCHAR(255);
    DECLARE v_genero_enum ENUM('H','M','Prefiero no decirlo');
    DECLARE v_pais_final CHAR(2);
    DECLARE v_fecha_nac DATE;
    DECLARE v_status BIT(1);
    DECLARE v_new_user_id INT UNSIGNED;
    DECLARE v_random_suffix INT;

    -- Manejo de errores SQL y control transaccional
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL SET MESSAGE_TEXT = 'Error en la ejecución de la simulación masiva de usuarios.';
    END;

    -- Validaciones de parámetros
    IF p_cantidad IS NULL OR p_cantidad <= 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La cantidad debe ser mayor a 0.';
    END IF;

    IF p_edad_min > p_edad_max THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'La edad mínima no puede ser mayor a la edad máxima.';
    END IF;

    START TRANSACTION;

    WHILE v_i <= p_cantidad DO
        IF p_genero = 'H' THEN 
            SET v_genero_enum = 'H';
        ELSEIF p_genero = 'M' THEN 
            SET v_genero_enum = 'M';
        ELSE 
            SET v_genero_enum = IF(RAND() < 0.5, 'H', 'M');
        END IF;

        SET v_nombre = fn_nombre_aleatorio(p_genero);
        SET v_apellido = CONCAT(fn_apellido_aleatorio(), ' ', fn_apellido_aleatorio());
        SET v_pais_final = fn_pais_aleatorio(p_pais);
        SET v_fecha_nac = fn_fecha_nacimiento_aleatoria(p_edad_min, p_edad_max);

        IF p_prob_activo IS NOT NULL AND p_prob_activo >= 0 THEN
            SET v_status = IF(RAND() <= p_prob_activo, b'1', b'0');
        ELSE
            SET v_status = b'1';
        END IF;

        SET v_random_suffix = FLOOR(100000 + (RAND() * 900000));
        SET v_nickname = CONCAT(LOWER(v_nombre), '.', LOWER(SUBSTRING_INDEX(v_apellido, ' ', 1)), '_', v_random_suffix);
        SET v_email = CONCAT(v_nickname, '@simulacion.com');
        SET v_password = SHA2(CONCAT('Pass_', v_random_suffix), 256);

        -- Inserción en tb_users
        INSERT INTO `tb_users` (`email`, `nickname`, `password`, `status`)
        VALUES (v_email, v_nickname, v_password, v_status);

        SET v_new_user_id = LAST_INSERT_ID();

        -- Inserción acoplada en tb_people
        INSERT INTO `tb_people` (
            `user_ID`, `given_names`, `family_names`, `birth_date`, 
            `gender_ID`, `country_code`, `status`
        )
        VALUES (
            v_new_user_id, v_nombre, v_apellido, v_fecha_nac, 
            v_genero_enum, v_pais_final, v_status
        );

        SET v_i = v_i + 1;
    END WHILE;

    COMMIT;

    SELECT CONCAT('Se han generado exitosamente ', p_cantidad, ' usuarios simulados.') AS mensaje_resultado;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
