CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_soft_delete_user`(
    IN p_user_id INT UNSIGNED
)
BEGIN
    DECLARE v_existe INT;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL SET MESSAGE_TEXT = 'Error al inhabilitar la cuenta del usuario.';
    END;

    SELECT COUNT(*) INTO v_existe FROM `tb_users` WHERE `ID` = p_user_id;

    IF v_existe = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El ID de usuario especificado no existe.';
    END IF;

    START TRANSACTION;
    UPDATE `tb_users` SET `status` = b'0' WHERE `ID` = p_user_id;
    UPDATE `tb_people` SET `status` = b'0' WHERE `user_ID` = p_user_id;
    COMMIT;

    SELECT CONCAT('El usuario con ID ', p_user_id, ' ha sido inhabilitado correctamente.') AS resultado;
END ;;
DELIMITER ;
